def layout(r, big):
    H = r.randint(7, 8) if big else r.randint(5, 6)
    W = r.randint(34, 40) if big else r.randint(22, 30)
    occ = set(); B = []
    def free(b, c):
        return 0 <= c <= W - 3 and all((b, c + k) not in occ for k in range(3))
    def put(b, c):
        for k in range(3): occ.add((b, c + k))
        B.append((b, c))
    for b in range(H):
        c = r.randint(0, 3)
        while c <= W - 3:
            if r.random() < 0.88: put(b, c)
            c += 3 + r.choice((0, 0, 0, 0, 1, 2))
    # edges: (i, j, width) with brick j one band above brick i
    E = []
    for i, (b1, c1) in enumerate(B):
        for j, (b2, c2) in enumerate(B):
            if b2 == b1 + 1 and abs(c1 - c2) < 3: E.append((i, j, 3 - abs(c1 - c2)))
    # keep the largest connected component
    adj = {i: set() for i in range(len(B))}
    for i, j, w in E: adj[i].add(j); adj[j].add(i)
    seen = set(); best = set()
    for s in range(len(B)):
        if s in seen: continue
        comp = {s}; Q = [s]
        while Q:
            u = Q.pop()
            for v in adj[u]:
                if v not in comp: comp.add(v); Q.append(v)
        seen |= comp
        if len(comp) > len(best): best = comp
    keep = sorted(best); idx = {old: new for new, old in enumerate(keep)}
    B = [B[i] for i in keep]
    E = [(idx[i], idx[j], w) for i, j, w in E if i in idx and j in idx]
    return B, E

def uniform(E):
    h = [sum(1 for e in E if e[2] == w) for w in (1, 2, 3)]
    return min(h) >= 0.27 * len(E) and max(h) <= 0.40 * len(E)

def render(B, lab, r):
    fill = r.choice("._-~:*")
    H = max(b for b, c in B) + 1; lo = min(c for b, c in B); W = max(c for b, c in B) + 3 - lo
    g = [[fill] * W for _ in range(2 * H)]
    for i, (b, c) in enumerate(B):
        for dr in (0, 1):
            for k in range(3): g[2 * (H - 1 - b) + dr][c - lo + k] = lab[i]
    return "\n".join("".join(row) for row in g)

def solve(clue):
    p, q, y = clue[0], clue[1], int(clue[2:])
    r = random.Random(clue)
    others = [ch for ch in string.ascii_uppercase if ch not in (p, q)]
    for attempt in range(400):
        B, E = layout(r, y >= 6)
        if len(E) < max(5 * y, 12) or not uniform(E): continue
        E2 = [e for e in E if e[2] == 2]
        lab = None
        for _ in range(30):
            r.shuffle(E2); P = set(); Q = set(); cnt = 0
            for i, j, w in E2:
                if cnt == y: break
                if r.random() < 0.5: i, j = j, i
                if i in Q or j in P: i, j = j, i
                if i in Q or j in P: continue
                P2, Q2 = P | {i}, Q | {j}
                c2 = sum(1 for a, b, ww in E2 if (a in P2 and b in Q2) or (a in Q2 and b in P2))
                if c2 <= y: P, Q, cnt = P2, Q2, c2
            if cnt != y: continue
            for i in r.sample(range(len(B)), len(B)):          # decoys: extra p/q bricks that add no 2-pin p-q edge
                if i in P or i in Q or r.random() > 0.3: continue
                side = r.choice((0, 1))
                S, T = (P, Q) if side == 0 else (Q, P)
                if not any(w == 2 and ((a == i and b in T) or (b == i and a in T)) for a, b, w in E2): S.add(i)
            pal = r.sample(others, 5)
            lab = [p if i in P else q if i in Q else r.choice(pal) for i in range(len(B))]
            if len(set(lab)) >= 5: break
            lab = None
        if lab: return render(B, lab, r)
    return ""

